"""Actual normal title Continue; old H and A saves are generated by running the archived/current builds."""
from pathlib import Path
from urllib.parse import urlsplit
import base64,json,sys
from guard import P,need,fact,save
from playwright.sync_api import sync_playwright
D=Path(__file__).resolve().parent
O=json.loads((D/'observer.json').read_bytes())
U={'A':'http://127.0.0.1:18845/','B':'http://127.0.0.1:18843/','H':'http://127.0.0.1:18844/'}
KEY='honro-first-act-profile-1'
COMMON=r"""
 const ids=['approved32:coastal-foundation','act4-handoff:32:body-joined'];
 const lists=b=>[b.honroLandmarks,b.honroElements,b.honroEnvironment?.placements];
 const places=b=>lists(b).flatMap(xs=>(xs||[]).filter(x=>ids.includes(x.assetId)));
 const valid=b=>Boolean(b&&b.mode==='campaign'&&b.honroStage===32&&b.stage===32&&
  b.honroCanonical===true&&b.honroCustom===false&&b.honroMapOrigin==='campaign'&&b.honroAct4Official===1);
 const sig=a=>{const s=JSON.stringify(a);let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return s.length+':'+(h>>>0).toString(16)};
 const state=b=>({terrain:JSON.stringify([b.terrain,b.honroWorldTerrain,b.honroPlayBounds,b.honroTerrainBounds]),
  units:JSON.stringify(b.units),objectives:JSON.stringify([b.honroObjectives,b.objectives,b.honroQuestTargets,b.honroGoalState,b.honroEncounterState]),
  phase:b.phase,round:b.round,revision:b.honroCampaignMapRevision,
  places:places(b).map(({asset,...x})=>x)});
 const rows=(b,fn)=>Object.fromEntries(ids.map(k=>[k,places(b).filter(x=>x.assetId===k).map(fn)]));
"""
PERSIST='key=>{'+COMMON+r"""
 const a=HonroApp;if(!valid(a.engine?.b)||a.profileStore.locked||a.screen!=='battle'||typeof a.flushBattleSave!=='function')throw Error('genuine legal app checkpoint unavailable');
 const previous=localStorage.getItem(key);
 a.dirty=true;a.flushBattleSave();
 const text=localStorage.getItem(key),p=JSON.parse(text),b=p.honroBattle;
 if(a.dirty||!text||!valid(b)||HonroCampaignMapRevision.obsolete(b)||JSON.stringify(state(b))!==JSON.stringify(state(a.engine.b)))
   throw Error('normal battle save did not contain the exact live checkpoint');
 if(places(b).some(x=>x.asset.honroStaticAssetRef!==1||x.asset.id!==x.assetId))throw Error('a signed role was not compacted by the real app');
 return {text,refs:rows(b,x=>x.asset.signature),state:state(b),samePriorBytes:text===previous,issuer:'HonroApp.flushBattleSave'};
}"""
RESTORED='()=>{'+COMMON+r"""
 const a=HonroApp,b=a.engine?.b;if(!valid(b)||a.profileStore.locked)throw Error('actual Continue did not mount a valid campaign battle');
 const out=Object.fromEntries(ids.map(k=>[k,HONRO_PROJECT.library.filter(x=>x.id===k).map(sig)]));
 return {state:state(b),active:out,mounted:rows(b,x=>sig(x.asset))};
}"""
NEG='text=>{'+COMMON+r"""
 const saved=JSON.parse(text).honroBattle;
 const test=f=>{const b=structuredClone(saved);f(b);const old=JSON.stringify(b);
  return !HonroProfileStore.restoreBattleArt(b)&&JSON.stringify(b)===old};
 const role=(b,n)=>places(b).find(x=>x.assetId===ids[n]);
 return {wrongStage:test(b=>b.honroStage=33),wrongMode:test(b=>b.mode='practice'),
  workshop:test(b=>b.honroMapOrigin='workshop'),custom:test(b=>b.honroCustom=true),
  nonOfficial:test(b=>b.honroAct4Official=0),badFoundation:test(b=>role(b,0).asset.signature='1:deadc0de'),
  badJoined:test(b=>role(b,1).asset.signature='3:badbad'),badSecondAtomic:test(b=>places(b).at(-1).asset.honroStaticAssetRef=2)};
}"""
def main(w):
 q={'status':'HOLD','scope':'Real archived/current/candidate app saves in fresh anonymous contexts. Synthetic QA slots only, exact owner F/B; no save exported.','devices':{}}
 rr=json.loads((w/'out'/'NATIVE-ROUTES.json').read_bytes())['routes']
 def report():save(w,'RESUME.json',q)
 report()
 with sync_playwright()as pw:
  ch=pw.chromium.launch(headless=True);q['browser']=ch.version
  need(ch.version=='151.0.7922.34','actual Chromium version')
  def opened(arm,d,old=None):
   u=U[arm];c=ch.new_context(viewport=dict(zip(('width','height'),d['dims'])),device_scale_factor=1,service_workers='block')
   need(c.storage_state()=={'cookies':[],'origins':[]},'fresh anonymized test context required')
   c.add_init_script('('+O['INIT']+')();'+O['INIT_SEED'])
   if old is not None:
    o=urlsplit(u);path=o.path+'HONRO.html';origin=f'{o.scheme}://{o.netloc}'
    need((origin,path) in [('http://127.0.0.1:18845','/HONRO.html'),('http://127.0.0.1:18843','/HONRO.html'),('http://127.0.0.1:18844','/HONRO.html')],'unknown test boot origin')
    c.add_init_script('if(location.origin==='+json.dumps(origin)+'&&location.pathname==='+json.dumps(path)+'){localStorage.setItem('+json.dumps(KEY)+','+json.dumps(old)+');}')
   p=c.new_page();net={};err=[]
   p.on('response',lambda h:net.setdefault(h.url,h) if h.url in {u+k for k in rr[arm]} else None)
   p.on('pageerror',lambda v:err.append(str(v)))
   nav=p.goto(u+'HONRO.html',wait_until='domcontentloaded',timeout=50000)
   need(nav and nav.status==200 and nav.url==u+'HONRO.html' and not nav.from_service_worker,'normal boot required')
   p.wait_for_function("()=>document.documentElement.dataset.honroReady==='true'&&typeof HonroCampaignLoader?.ensureStage==='function'",timeout=90000)
   p.evaluate("()=>{__honroResetDiagnosticSeed();HonroApp.audio?.configure?.({...HonroApp.profile.settings,music:false,sound:false});}")
   return c,p,net,err
  def ready(p):
   p.wait_for_function("()=>HonroApp.engine?.b?.honroStage===32&&!HonroApp.profileStore.locked",timeout=22000)
  def routes(arm,net):
   out={}
   for k,pin in rr[arm].items():
    z=net.get(U[arm]+k)
    need(z and z.status==200 and not z.from_service_worker and fact(z.body())==pin,('real HTTP resume bytes',arm,k))
    out[k]=pin
   return out
  def shot(p,d,case):
   a={'id':32,'mapId':'stage-32','name':'south','dx':0,'dy':1,'readback':False,'fixedNow':O['PHASE']}
   meta=p.evaluate(O['FROZEN'],a)['meta'];p.evaluate(O['DECODE']);p.evaluate(O['FROZEN'],{**a,'readback':True})
   from capture import same_nums
   need(same_nums({k:meta[k]for k in ('actual','viewport','backing')},{k:d[k]for k in ('actual','viewport','backing')}),'resume camera differs')
   x=base64.b64decode(p.evaluate(O['CANVAS']),validate=True);f=d['device']+'-resume-'+case+'.png'
   (w/'out'/f).write_bytes(x)
   return {'path':f,**fact(x)}
  rows=P['rows']
  expected={'H':{k:v['previous']for k,v in rows.items()},'A':{k:v.get('previousOptimized',v['previous'])for k,v in rows.items()},
            'B':{k:v['current']for k,v in rows.items()}}
  try:
   for d in (x for x in P['devs'] if x['name']=='south'):
    log=q['devices'][d['device']]={};setup={}
    for arm in ('H','A','B'):
     c=None
     try:
      c,p,net,err=opened(arm,d)
      p.evaluate(O['LAUNCH'],32);ready(p)
      s=p.evaluate(PERSIST,KEY)
      log['generate-'+arm]={'actualTokenRefs':s['refs'],'saved':fact(s['text'].encode()),'issuer':s['issuer'],'samePriorBytes':s['samePriorBytes'],'HTTP':routes(arm,net)};report()
      need(not err and all(s['refs'][k] and all(x==sig for x in s['refs'][k])for k,sig in expected[arm].items()),
       ('actual emitted stock/approved token does not match, no substitution',arm,s['refs']))
      setup[arm]=s
     except Exception as e:
      log.setdefault('generate-'+arm,{})['error']=repr(e);print(d['device'],arm,repr(e),flush=True);report()
     finally:
      if c:c.close()
    for arm,src in [('H','H'),('A','A'),('B','H'),('B','A'),('B','B')]:
     case=src+'-to-'+arm
     if src not in setup:
      log[case]={'error':'required exact browser-generated save missing'};report();continue
     s=setup[src];c=None
     try:
      c,p,net,err=opened(arm,d,s['text'])
      need(p.evaluate("()=>!HonroApp.engine&&Boolean(HonroApp.profile.honroBattle)"),'cold checkpoint not available')
      p.evaluate("()=>{HonroApp.frame=()=>{};HonroApp.continue();}");ready(p)
      z=p.evaluate(RESTORED)
      need(z['state']==s['state'] and all(z['active'][k]==[v] and z['mounted'][k] and all(x==v for x in z['mounted'][k])for k,v in expected[arm].items()),
           'restored real stage state, terrain, objects, or provider drift')
      v={'physicalAndStateExact':True,'mounts':z['mounted'],'HTTP':routes(arm,net),'raw':shot(p,d,case)}
      if arm=='B' and src in ('A','H'):
       v['negatives']=p.evaluate(NEG,s['text'])
       need(len(v['negatives'])==8 and all(v['negatives'].values()),'accepted unrelated signature or stage')
      need(not err,('unexpected normal runtime errors',err))
      log[case]=v;report()
     except Exception as e:
      log[case]={'error':repr(e)};print(d['device'],case,repr(e),flush=True);report()
     finally:
      if c:c.close()
  finally:ch.close()
 need(set(q['devices'])=={'PC','Mobile'} and all(len(d)==8 and not any('error'in v for v in d.values()) for d in q['devices'].values()),'one or more actual stock/candidate historical verification cases HOLD')
 q['status']='PASS_ACTUAL_STAGE32_R10_ARCHIVED_CURRENT_AND_NEW_COLD_RESUME_PC_M_NO_DEPLOY';report()
if __name__=='__main__':main(Path(sys.argv[1]))
